1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import org.springframework.samples.petclinic.model.Owner;
4	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
5	
6	/**
7	 * Derives an owner's {@code identityKey}, the single value all duplicate detection is expressed
8	 * through: the SHA-256 hex of {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}.
9	 * Two owners are duplicates only when their whole keys match; because the telephone is part of the key,
10	 * household members with different telephones have different keys and are both allowed.
11	 */
12	public final class IdentityKey {
13	
14	    private IdentityKey() {
15	    }
16	
17	    /** The key a create request would take once saved. */
18	    public static String forRequest(OwnerFieldsDto request) {
19	        return key(request.getTelephone(), request.getEmail(), request.getLastName());
20	    }
21	
22	    /** The key of an existing owner. */
23	    public static String forOwner(Owner owner) {
24	        return key(owner.getTelephone(), owner.getEmail(), owner.getLastName());
25	    }
26	
27	    private static String key(String telephone, String email, String lastName) {
28	        return sha256Hex(E164.toE164(telephone) + "|" + lower(email) + "|" + Soundex.of(lastName));
29	    }
30	
31	    /**
32	     * The deterministic household id: the first 12 hex characters of SHA-256 over
33	     * {@code normalizedLastName + '|' + postcode}. Owners with the same last name and postcode
34	     * therefore compute the same value and share a household automatically. Null when no postcode.
35	     */
36	    public static String household(String lastName, String postcode) {
37	        if (postcode == null || postcode.isEmpty()) {
38	            return null;
39	        }
40	        return sha256Hex12(normalize(lastName) + "|" + postcode);
41	    }
42	
43	    private static String sha256Hex12(String value) {
44	        return sha256Hex(value).substring(0, 12);
45	    }
46	
47	    private static String sha256Hex(String value) {
48	        try {
49	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
50	                    .digest(value.getBytes(java.nio.charset.StandardCharsets.UTF_8));
51	            StringBuilder hex = new StringBuilder(digest.length * 2);
52	            for (byte b : digest) {
53	                hex.append(String.format("%02x", b));
54	            }
55	            return hex.toString();
56	        }
57	        catch (java.security.NoSuchAlgorithmException e) {
58	            throw new IllegalStateException(e);
59	        }
60	    }
61	
62	    private static String normalize(String value) {
63	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase();
64	    }
65	
66	    private static String lower(String value) {
67	        return value == null ? "" : value.toLowerCase();
68	    }
69	}
