1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	/**
4	 * Computes the {@code checkDigit}: a single Luhn check digit over the digits contained in a
5	 * customer code. Non-digit characters (such as the '-' separators) are skipped.
6	 */
7	public final class CheckDigit {
8	
9	    private CheckDigit() {
10	    }
11	
12	    /** The Luhn check digit (0-9) over the digits in {@code code}. */
13	    public static int of(String code) {
14	        int sum = 0;
15	        boolean dbl = true;
16	        for (int i = code.length() - 1; i >= 0; i--) {
17	            char c = code.charAt(i);
18	            if (c < '0' || c > '9') {
19	                continue;
20	            }
21	            int d = c - '0';
22	            if (dbl && (d *= 2) > 9) {
23	                d -= 9;
24	            }
25	            sum += d;
26	            dbl = !dbl;
27	        }
28	        return (10 - (sum % 10)) % 10;
29	    }
30	}
