3	import java.time.LocalDate;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * Fiscal-year basis for date-derived owner values. The fiscal year starts on 1 July and is
9	 * labelled by the calendar year it ends in, taken from the business-day-adjusted registration date.
10	 */
11	public final class FiscalYear {
12	
13	    private FiscalYear() {
14	    }
15	
16	    /** The fiscal year (the calendar year it ends in) of a business-day-adjusted date. */
17	    public static int of(LocalDate date) {
18	        LocalDate rolled = BusinessDay.roll(date);
19	        return rolled.getMonthValue() >= 7 ? rolled.getYear() + 1 : rolled.getYear();
20	    }
21	
22	    /** {@code FY<YY>} for an owner's registration date. */
23	    public static String label(Owner owner) {
24	        return "FY" + String.format("%02d", of(owner.getRegistrationDate()) % 100);
25	    }
26	
27	    /** Elapsed fiscal years between an owner's registration date and today. */
28	    public static int tenure(Owner owner) {
29	        LocalDate registration = owner.getRegistrationDate();
30	        return registration == null ? 0 : of(LocalDate.now()) - of(registration);
31	    }
32	}
