1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import org.springframework.samples.petclinic.model.Owner;
4	
5	/**
6	 * Scores an owner's membership. {@link #points(Owner)} sums the owner-only factors — +2 for an
7	 * email on file, +1 for no namesake, +3 for a tenure of one or more elapsed fiscal years since
8	 * {@code registrationDate} (the household factor is added later, where the repository is available).
9	 * {@link #level(int)} buckets a point total into the 1-4 membership level.
10	 */
11	public final class MembershipLevel {
12	
13	    private MembershipLevel() {
14	    }
15	
16	    public static int points(Owner owner) {
17	        int points = 0;
18	        if (owner.getEmail() != null && !owner.getEmail().isEmpty()) {
19	            points += 2;
20	        }
21	        if (Integer.valueOf(0).equals(owner.getNamesakeCount())) {
22	            points += 1;
23	        }
24	        if (FiscalYear.tenure(owner) >= 1) {
25	            points += 3;
26	        }
27	        return points;
28	    }
29	
30	    public static int level(int points) {
31	        if (points <= 1) {
32	            return 1;
33	        }
34	        if (points <= 3) {
35	            return 2;
36	        }
37	        if (points <= 5) {
38	            return 3;
39	        }
40	        return 4;
41	    }
42	}
