3	/**
4	 * Derives an owner's segment as {@code <TIER>_<AREA>}. TIER is {@code PREMIUM} when the
5	 * membershipLevel is 3 or more, otherwise {@code STANDARD}. AREA is {@code METRO} when the locality
6	 * is a known region (NSW, VIC or QLD), otherwise {@code REGIONAL}.
7	 */
8	public final class OwnerSegment {
9	
10	    private OwnerSegment() {
11	    }
12	
13	    public static String of(int membershipLevel, String locality) {
14	        String tier = membershipLevel >= 3 ? "PREMIUM" : "STANDARD";
15	        String area = switch (locality) {
16	            case "NSW", "VIC", "QLD" -> "METRO";
17	            default -> "REGIONAL";
18	        };
19	        return tier + "_" + area;
20	    }
21	}
