1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import org.springframework.samples.petclinic.model.Owner;
4	import org.springframework.samples.petclinic.repository.OwnerRepository;
5	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
6	
7	/**
8	 * Adds the household membership-points factor: +2 points when the owner's household (owners sharing
9	 * the same {@code householdId}) has three or more members. Applied after the owner-only points have
10	 * been mapped, then the membership level is recomputed; owners without a household are left untouched.
11	 */
12	final class HouseholdTier {
13	
14	    private HouseholdTier() {
15	    }
16	
17	    static void applyGold(Owner owner, OwnerRepository ownerRepository, OwnerDto dto) {
18	        String householdId = owner.getHouseholdId();
19	        if (householdId == null) {
20	            return;
21	        }
22	        int members = 0;
23	        for (Owner existing : ownerRepository.findAll()) {
24	            if (householdId.equals(existing.getHouseholdId())) {
25	                members++;
26	            }
27	        }
28	        if (members >= 3) {
29	            int points = dto.getMembershipPoints() + 2;
30	            dto.setMembershipPoints(points);
31	            dto.setMembershipLevel(MembershipLevel.level(points));
32	        }
33	        // A new member's level may sit at most one above the current household maximum.
34	        int bonus = members >= 3 ? 2 : 0;
35	        int maxOther = -1;
36	        for (Owner existing : ownerRepository.findAll()) {
37	            if (!householdId.equals(existing.getHouseholdId())
38	                    || (existing.getId() != null && existing.getId().equals(owner.getId()))) {
39	                continue;
40	            }
41	            maxOther = Math.max(maxOther, MembershipLevel.level(MembershipLevel.points(existing) + bonus));
42	        }
43	        if (maxOther >= 0 && dto.getMembershipLevel() > maxOther + 1) {
44	            dto.setMembershipLevel(maxOther + 1);
45	        }
46	    }
47	}
