1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	/**
4	 * American Soundex of a surname: the first letter followed by three consonant-class digits. Used as
5	 * the phonetic component of an owner's {@link IdentityKey} and as the soft-match key (similar-sounding
6	 * last names in the same postcode). Empty for a null or letter-free name.
7	 */
8	public final class Soundex {
9	
10	    private Soundex() {
11	    }
12	
13	    public static String of(String name) {
14	        String s = name == null ? "" : name.replaceAll("[^A-Za-z]", "").toUpperCase();
15	        if (s.isEmpty()) {
16	            return "";
17	        }
18	        StringBuilder code = new StringBuilder().append(s.charAt(0));
19	        char prev = digit(s.charAt(0));
20	        for (int i = 1; i < s.length() && code.length() < 4; i++) {
21	            char c = s.charAt(i);
22	            char d = digit(c);
23	            if (d != '0' && d != prev) {
24	                code.append(d);
25	            }
26	            if (c != 'H' && c != 'W') {
27	                prev = d;
28	            }
29	        }
30	        while (code.length() < 4) {
31	            code.append('0');
32	        }
33	        return code.toString();
34	    }
35	
36	    private static char digit(char c) {
37	        switch (c) {
38	            case 'B': case 'F': case 'P': case 'V': return '1';
39	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z': return '2';
40	            case 'D': case 'T': return '3';
41	            case 'L': return '4';
42	            case 'M': case 'N': return '5';
43	            case 'R': return '6';
44	            default: return '0';
45	        }
46	    }
47	}
