3	/**
4	 * Converts a raw telephone into E.164 form. A leading '+' with its country code is kept; otherwise
5	 * country code '+61' is assumed and a single leading '0' is dropped from the national digits. Spaces,
6	 * dashes and brackets are stripped. Returns {@code null} when the result is not 8 to 15 digits.
7	 */
8	public final class E164 {
9	
10	    private E164() {
11	    }
12	
13	    public static String toE164(String raw) {
14	        if (raw == null) {
15	            return null;
16	        }
17	        boolean explicit = raw.trim().startsWith("+");
18	        String digits = raw.replaceAll("\\D", "");
19	        if (!explicit) {
20	            if (digits.startsWith("0")) {
21	                digits = digits.substring(1);
22	            }
23	            digits = "61" + digits;
24	        }
25	        if (digits.length() < 8 || digits.length() > 15) {
26	            return null;
27	        }
28	        return "+" + digits;
29	    }
30	}
