3	import java.time.DayOfWeek;
4	import java.time.LocalDate;
5	import java.util.Set;
6	
7	/**
8	 * Rolls a date forward onto a business day: weekends and listed public holidays roll forward
9	 * to the next non-holiday weekday. Used for the effective registration date and everything derived from it.
10	 */
11	public final class BusinessDay {
12	
13	    private static final Set<LocalDate> HOLIDAYS = Set.of(
14	            LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
15	            LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"), LocalDate.parse("2026-12-28"));
16	
17	    private BusinessDay() {
18	    }
19	
20	    private static boolean isBusinessDay(LocalDate date) {
21	        DayOfWeek day = date.getDayOfWeek();
22	        return day != DayOfWeek.SATURDAY && day != DayOfWeek.SUNDAY && !HOLIDAYS.contains(date);
23	    }
24	
25	    public static LocalDate roll(LocalDate date) {
26	        while (!isBusinessDay(date)) {
27	            date = date.plusDays(1);
28	        }
29	        return date;
30	    }
31	}
