29	            if (postcode.equals(existing.getPostcode())
30	                    && soundex.equals(Soundex.of(existing.getLastName()))
31	                    && !identityKey.equals(IdentityKey.forOwner(existing))) {
32	                owner.setPossibleDuplicateOf(existing.getId());
